public enum UiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Invalid(reason: String
    )
    /**
     * A theme failed to load; `issues_json` = `[{path, message}]`.
     */
    case Theme(issuesJson: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension UiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeUiError: FfiConverterRustBuffer {
    typealias SwiftType = UiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> UiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Invalid(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Theme(
            issuesJson: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: UiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Invalid(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Theme(issuesJson):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(issuesJson, into: &buf)
            
        }
    }
}


